def chain_follows(chain):
    tokens = list(chain)
    tokens.sort()
    chain_len = len(tokens)
    if chain_len == 1:
        return tokens[0]

    chain_dict = {}
    for i in range(chain_len):
        current = tokens[i]
        next_token = tokens[(i + 1) % chain_len]
        if current not in chain_dict:
            chain_dict[current] = next_token
        else:
            chain_dict[current] = chain_dict[next_token]

    current = tokens[0]
    result = []
    while current in chain_dict:
        result.append(current)
        current = chain_dict[current]
    result.append(current)
    return ','.join(result)
